SELECT 'ROWS_EXAMPLE_STOCK' AS CHECK_NAME, (SELECT ABS(COUNT(*) - 75) FROM EXAMPLE_STOCK) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'ROWS_MISSING' AS CHECK_NAME, (SELECT COUNT(*) FROM want w WHERE NOT EXISTS (SELECT 1 FROM EXAMPLE_STOCK e WHERE e.CSV_ROW = w.CSV_ROW)) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'META_EXAMPLE_STOCK' AS CHECK_NAME, (SELECT COUNT(*) FROM want w JOIN EXAMPLE_STOCK e ON e.CSV_ROW = w.CSV_ROW WHERE NOT (DECODE(e.COMPLEX_ID, w.COMPLEX_ID, 0, 1) = 0 AND DECODE(e.LAYER, w.LAYER, 0, 1) = 0 AND DECODE(e.SPLIT, w.SPLIT, 0, 1) = 0 AND e.MEMBER_NO = (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid'))) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'STOCK_INFO_19_COLUMNS' AS CHECK_NAME, (SELECT COUNT(*) FROM want w JOIN EXAMPLE_STOCK e ON e.CSV_ROW = w.CSV_ROW LEFT JOIN STOCK_INFO s ON s.STOCK_NO = e.STOCK_NO WHERE s.STOCK_NO IS NULL OR NOT (DECODE(s.STOCK_NAME, w.STOCK_NAME, 0, 1) = 0 AND DECODE(s.STOCK_SELL_PRICE, w.STOCK_SELL_PRICE, 0, 1) = 0 AND DECODE(s.STOCK_MANAGE_FEE, w.STOCK_MANAGE_FEE, 0, 1) = 0 AND DECODE(s.STOCK_FEE_MONTH, w.STOCK_FEE_MONTH, 0, 1) = 0 AND DECODE(s.STOCK_INFO, w.STOCK_INFO, 0, 1) = 0 AND DECODE(s.STOCK_TYPE, w.STOCK_TYPE, 0, 1) = 0 AND DECODE(s.STOCK_FORM, w.STOCK_FORM, 0, 1) = 0 AND DECODE(s.EXCLUSIVE_AREA, w.EXCLUSIVE_AREA, 0, 1) = 0 AND DECODE(s.SUPPLY_AREA, w.SUPPLY_AREA, 0, 1) = 0 AND DECODE(s.CURRENT_FLOOR, w.CURRENT_FLOOR, 0, 1) = 0 AND DECODE(s.FLOOR_TOTAL_COUNT, w.FLOOR_TOTAL_COUNT, 0, 1) = 0 AND DECODE(s.ROOM_COUNT, w.ROOM_COUNT, 0, 1) = 0 AND DECODE(s.BATH_COUNT, w.BATH_COUNT, 0, 1) = 0 AND DECODE(s.STOCK_DIRECTION, w.STOCK_DIRECTION, 0, 1) = 0 AND DECODE(s.ABLE_DATE, w.ABLE_DATE, 0, 1) = 0 AND DECODE(s.USE_APPROVAL_DATE, w.USE_APPROVAL_DATE, 0, 1) = 0 AND DECODE(s.STOCK_DETAIL, w.STOCK_DETAIL, 0, 1) = 0 AND DECODE(s.STOCK_ADDRESS, w.STOCK_ADDRESS, 0, 1) = 0 AND DECODE(s.REGION_NO, w.REGION_NO, 0, 1) = 0)) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'STOCK_INFO_OTHERS' AS CHECK_NAME, (SELECT COUNT(*) FROM EXAMPLE_STOCK e LEFT JOIN STOCK_INFO s ON s.STOCK_NO = e.STOCK_NO WHERE s.STOCK_NO IS NULL OR NOT (s.MEMBER_NO = (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid') AND s.SELL_YN = 'N' AND s.REGIST_DATE IS NOT NULL AND s.ABLE_DATE = TRUNC(s.ABLE_DATE) AND s.USE_APPROVAL_DATE = TRUNC(s.USE_APPROVAL_DATE))) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'SELL_DATE_NULL' AS CHECK_NAME, (SELECT COUNT(*) FROM EXAMPLE_STOCK e WHERE NOT EXISTS (SELECT 1 FROM SELL_DATE d WHERE d.STOCK_NO = e.STOCK_NO AND d.SELL_DATE IS NULL) OR (SELECT COUNT(*) FROM SELL_DATE d WHERE d.STOCK_NO = e.STOCK_NO) <> 1) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'STOCK_COORD' AS CHECK_NAME, (SELECT COUNT(*) FROM want w JOIN EXAMPLE_STOCK e ON e.CSV_ROW = w.CSV_ROW WHERE NOT EXISTS (SELECT 1 FROM STOCK_COORD c WHERE c.STOCK_NO = e.STOCK_NO AND c.LAT = w.LAT AND c.LNG = w.LNG) OR (SELECT COUNT(*) FROM STOCK_COORD c WHERE c.STOCK_NO = e.STOCK_NO) <> 1) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'STOCK_IMG' AS CHECK_NAME, (SELECT COUNT(*) FROM EXAMPLE_STOCK e WHERE NOT (EXISTS (SELECT 1 FROM STOCK_IMG i WHERE i.STOCK_NO = e.STOCK_NO AND i.IMG_ORDER = 0 AND i.IMG_URL = '/myPage/stockImg/zipinfo_example_v2_0_thumb.png' AND i.IMG_ORIGIN_NAME = 'zipinfo_example_v2_0_thumb.png' AND i.IMG_RENAME = 'zipinfo_example_v2_0_thumb.png') AND EXISTS (SELECT 1 FROM STOCK_IMG i WHERE i.STOCK_NO = e.STOCK_NO AND i.IMG_ORDER = 1 AND i.IMG_URL = '/myPage/stockImg/zipinfo_example_v2_1_floorplan.png' AND i.IMG_ORIGIN_NAME = 'zipinfo_example_v2_1_floorplan.png' AND i.IMG_RENAME = 'zipinfo_example_v2_1_floorplan.png') AND EXISTS (SELECT 1 FROM STOCK_IMG i WHERE i.STOCK_NO = e.STOCK_NO AND i.IMG_ORDER = 2 AND i.IMG_URL = '/myPage/stockImg/zipinfo_example_v2_2_photo.png' AND i.IMG_ORIGIN_NAME = 'zipinfo_example_v2_2_photo.png' AND i.IMG_RENAME = 'zipinfo_example_v2_2_photo.png')) OR (SELECT COUNT(*) FROM STOCK_IMG i WHERE i.STOCK_NO = e.STOCK_NO) <> 3) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'MEMBER_ACCOUNT' AS CHECK_NAME, (SELECT ABS(COUNT(*) - 1) FROM MEMBER m WHERE m.MEMBER_EMAIL = 'example-listings@example.invalid' AND m.MEMBER_PW = 'LOGIN-DISABLED' || CHR(58) || 'EXAMPLE-ACCOUNT' AND m.MEMBER_IMG IS NULL AND m.MEMBER_DEL_FL = 'N' AND m.MEMBER_LOGIN = 'E' AND DECODE(m.MEMBER_NICKNAME, UNISTR('\C9D1\C778\D3EC \C608\C2DC \B9E4\BB3C'), 0, 1) = 0 AND DECODE(m.MEMBER_NAME, UNISTR('\C608\C2DC'), 0, 1) = 0 AND m.MEMBER_AUTH = 3 AND m.ACCESS_TOKEN IS NULL AND m.MEMBER_LOCATION IS NULL AND m.MEMBER_WITHDRAW_DATE IS NULL AND m.ENROLL_DATE IS NOT NULL) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'TOKEN_INFO' AS CHECK_NAME, (SELECT ABS(COUNT(*) - 1) FROM TOKEN_INFO t WHERE t.MEMBER_NO IN (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid') AND t.TOKEN_INFO IS NULL) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'BROKER_INFO' AS CHECK_NAME, (SELECT ABS(COUNT(*) - 1) FROM BROKER_INFO b WHERE b.MEMBER_NO IN (SELECT MEMBER_NO FROM MEMBER WHERE MEMBER_EMAIL = 'example-listings@example.invalid') AND DECODE(b.COMPANY_NAME, UNISTR('\C9D1\C778\D3EC \C608\C2DC \B9E4\BB3C(\C2E4\C81C \C911\AC1C\C0AC \C544\B2D8)'), 0, 1) = 0 AND DECODE(b.COMPANY_LOCATION, UNISTR('00000^^^\C608\C2DC \B9E4\BB3C \C548\B0B4\C6A9(\C2E4\C81C \C0AC\BB34\C18C \C544\B2D8)^^^'), 0, 1) = 0 AND DECODE(b.PRESIDENT_NAME, UNISTR('\C608\C2DC'), 0, 1) = 0 AND DECODE(b.BROKER_NO, UNISTR('\C5C6\C74C(\C608\C2DC \ACC4\C815)'), 0, 1) = 0 AND DECODE(b.PRESIDENT_PHONE, UNISTR('000-0000-0000'), 0, 1) = 0) AS BAD, CAST(NULL AS VARCHAR2(60)) AS UTC_TIME, CAST(NULL AS VARCHAR2(60)) AS KST_TIME FROM DUAL
UNION ALL
SELECT 'REGIST_DATE_RANGE', 0, (SELECT TO_CHAR(MIN(s.REGIST_DATE), 'YYYY-MM-DD HH24.MI.SS') || ' ~ ' || TO_CHAR(MAX(s.REGIST_DATE), 'YYYY-MM-DD HH24.MI.SS') FROM STOCK_INFO s JOIN EXAMPLE_STOCK e ON e.STOCK_NO = s.STOCK_NO), (SELECT TO_CHAR(MIN(s.REGIST_DATE) + 9/24, 'YYYY-MM-DD HH24.MI.SS') || ' ~ ' || TO_CHAR(MAX(s.REGIST_DATE) + 9/24, 'YYYY-MM-DD HH24.MI.SS') FROM STOCK_INFO s JOIN EXAMPLE_STOCK e ON e.STOCK_NO = s.STOCK_NO) FROM DUAL
UNION ALL
SELECT 'DB_CLOCK_NOW', 0, TO_CHAR(SYSTIMESTAMP, 'YYYY-MM-DD HH24.MI.SS TZH.TZM'), CAST(NULL AS VARCHAR2(60)) FROM DUAL
UNION ALL
SELECT 'ENROLL_DATE', 0, (SELECT TO_CHAR(MAX(m.ENROLL_DATE), 'YYYY-MM-DD HH24.MI.SS') FROM MEMBER m WHERE m.MEMBER_EMAIL = 'example-listings@example.invalid'), (SELECT TO_CHAR(MAX(m.ENROLL_DATE) + 9/24, 'YYYY-MM-DD HH24.MI.SS') FROM MEMBER m WHERE m.MEMBER_EMAIL = 'example-listings@example.invalid') FROM DUAL;
